function ReciboPreview({
  cliente,
  dataPedido,
  itens,
  taxaEntrega,
  mode = "preview",
}: {
  cliente: string;
  dataPedido: string;
  itens: ReciboItem[];
  taxaEntrega: number;
  mode?: "preview" | "export";
}) {
  const itensValidos = itens.filter(
  (item) =>
    item.sabor.trim() ||
    (Number(item.quantidade) || 0) > 0 ||
    (Number(item.valorUnitario) || 0) > 0
);

 const subtotal = itensValidos.reduce((acc, item) => {
  const quantidade = Number(item.quantidade) || 0;
  const valorUnitario = Number(item.valorUnitario) || 0;
  return acc + quantidade * valorUnitario;
}, 0);

  const total = subtotal + (Number(taxaEntrega) || 0);

  return (
    <div
  className={`receipt-paper ${mode === "export" ? "receipt-export" : ""}`}
>
      <img
  src={LOGO_URL}
  alt="Le Petit Quicheria"
  className="receipt-logo"
  loading="eager"
  decoding="sync"
/>

      <div className="receipt-title">Le petit Quicheria</div>

      <div className="receipt-header">
        <div>
          <strong>Cliente:</strong> {cliente || "________________"}
        </div>
        <div>
          <strong>Data do pedido:</strong>{" "}
          {dataPedido ? formatDateBR(dataPedido) : "__/__/____"}
        </div>
      </div>

      <div className="receipt-items">
        {itensValidos.map((item) => {
          const totalItem =
  (Number(item.quantidade) || 0) * (Number(item.valorUnitario) || 0);
          return (
            <div key={item.id} className="receipt-line">
             <span className="receipt-item-text">
  {item.quantidade}x{" "}
  {Number(item.quantidade) > 1 ? "Quiches de" : "Quiche de"}{" "}
  {(item.sabor || "Item").charAt(0).toUpperCase() +
    (item.sabor || "Item").slice(1)}
</span>
              <span className="receipt-dots" />
              <span className="receipt-item-value">
                {formatCurrency(totalItem)}
              </span>
            </div>
          );
        })}

        {(Number(taxaEntrega) || 0) > 0 && (
          <div className="receipt-line">
            <span className="receipt-item-text">Entrega</span>
            <span className="receipt-dots" />
            <span className="receipt-item-value">
              {formatCurrency(Number(taxaEntrega) || 0)}
            </span>
          </div>
        )}
      </div>

      <div className="receipt-total">Total: {formatCurrency(total)}</div>
    </div>
  );
}

