const waitForImagesToLoad = async (container: HTMLElement) => {
  const images = Array.from(container.querySelectorAll("img"));

  await Promise.all(
    images.map((img) => {
      if (img.complete && img.naturalWidth > 0) return Promise.resolve();

      return new Promise<void>((resolve) => {
        const done = () => resolve();
        img.addEventListener("load", done, { once: true });
        img.addEventListener("error", done, { once: true });
      });
    })
  );
};
  const gerarImagemRecibo = async () => {
  if (!reciboExportRef.current) return;

  try {
    await waitForImagesToLoad(reciboExportRef.current);

   const exportNode = reciboExportRef.current;
const exportWidth = 1080;
const exportHeight = exportNode.scrollHeight;

const dataUrl = await toPng(exportNode, {
  cacheBust: true,
  pixelRatio: 1,
  backgroundColor: "#ffffff",
  canvasWidth: exportWidth,
  canvasHeight: exportHeight,
  width: exportWidth,
  height: exportHeight,
});

    const response = await fetch(dataUrl);
    const blob = await response.blob();
    const file = new File([blob], `recibo-${cliente || "cliente"}.png`, {
      type: "image/png",
    });

    const canShareFile =
      typeof navigator !== "undefined" &&
      "share" in navigator &&
      "canShare" in navigator &&
      navigator.canShare({ files: [file] });

    if (canShareFile) {
      await navigator.share({
        title: "Recibo - Le Petit Quicheria",
        text: "Recibo - Le Petit Quicheria",
        files: [file],
      });
      return;
    }

    const link = document.createElement("a");
    link.download = `recibo-${cliente || "cliente"}-${
      dataPedido || getTodayStr()
    }.png`;
    link.href = dataUrl;
    link.click();
  } catch (error) {
    console.error(error);
    alert("Não foi possível gerar a imagem do recibo.");
  }
};

  const handlePrint = () => {
    const sheets = document.querySelectorAll<HTMLElement>(".print-area .sheet");
    if (!sheets.length) return;

    const printWindow = window.open(
      "",
      "_blank",
      `width=${screen.availWidth},height=${screen.availHeight},left=0,top=0`
    );
    if (!printWindow) return;

    // Collect only the .sheet elements — no wrapper divs, no script in body.
    // This guarantees .sheet:last-child is unambiguous and wrappers cannot
    // add phantom height that generates blank pages in WebKit.
    const sheetsHtml = Array.from(sheets)
      .map((el) => el.outerHTML)
      .join("\n");

    printWindow.document.write(`<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8" />
    <title>Etiquetas</title>
    <style>${PRINT_CSS}</style>
    <script>
      // Only call window.print() after every image is loaded AND decoded,
      // plus two animation frames so the layout is fully rasterized.
      // Printing straight from onload occasionally captured the document
      // before the logo images were painted, producing blank labels.
      function whenImagesReady() {
        var imgs = Array.prototype.slice.call(document.images);
        return Promise.all(
          imgs.map(function (img) {
            if (img.decode) return img.decode().catch(function () {});
            if (img.complete) return Promise.resolve();
            return new Promise(function (resolve) {
              img.addEventListener("load", resolve, { once: true });
              img.addEventListener("error", resolve, { once: true });
            });
          })
        );
      }
      window.onload = function () {
        whenImagesReady().then(function () {
          requestAnimationFrame(function () {
            requestAnimationFrame(function () {
              window.print();
            });
          });
        });
      };
      window.onafterprint = function () { window.close(); };
    <\/script>
  </head>
  <body>
    ${sheetsHtml}
  </body>
</html>`);

    printWindow.document.close();
  };

